def main():
    with open(AR_PATH, 'r', encoding='utf-8') as f:
        ar_data = json.load(f)

    products = ar_data.get('products', {})

    # 1. Remove ghost packaging-kraft entry
    if 'packaging-kraft' in products:
        del products['packaging-kraft']
        print("Removed ghost entry: packaging-kraft")

    # 2. Apply Arabic descriptions
    fixed = 0
    added = 0
    for slug, arabic_desc in AR_DESCRIPTIONS.items():
        if slug not in products:
            products[slug] = {}
            products[slug]['description'] = arabic_desc
            added += 1
            print(f"  ADDED new entry: {slug}")
        else:
            existing = products[slug].get('description', '')
            # Only update if it's English or empty
            if not existing or all(ord(c) < 0x0600 for c in existing if c.strip()):
                products[slug]['description'] = arabic_desc
                fixed += 1
                print(f"  FIXED: {slug}")
            else:
                # Already Arabic — skip
                pass

    ar_data['products'] = products

    with open(AR_PATH, 'w', encoding='utf-8') as f:
        json.dump(ar_data, f, ensure_ascii=False, indent=2)

    print(f"\nDone. Fixed: {fixed}, Added new: {added}")

if __name__ == '__main__':
    main()
